package com.stocksense.dashboard; import com.stocksense.product.ProductRepository; import com.stocksense.inventory.stock.StockBalanceRepository; import com.stocksense.ledger.StockMovementRepository; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.math.BigDecimal; import java.util.*; @RestController @RequestMapping("/api/dashboard") @RequiredArgsConstructor public class DashboardController { private final ProductRepository products; private final StockBalanceRepository balances; private final StockMovementRepository moves; @GetMapping("/kpis") public Map<String,Object> kpis(){long low=balances.findAll().stream().filter(b->b.getQuantityOnHand().compareTo(b.getProduct().getMinimumStock())<=0).count(); long out=balances.findAll().stream().filter(b->b.getQuantityOnHand().compareTo(BigDecimal.ZERO)==0).count(); return Map.of("totalProducts",products.count(),"lowStock",low,"outOfStock",out,"stockLocations",balances.count(),"ledgerMovements",moves.count());} }
